import{_ as a,o as s,c as e,a2 as l}from"./chunks/framework.CnJ-JtFX.js";const k=JSON.parse('{"title":"EP.05 联动不是监听，是维护依赖图","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.05-formily-linkage.md","filePath":"comics/EP.05-formily-linkage.md","lastUpdated":1792683644000}'),t={name:"comics/EP.05-formily-linkage.md"};function n(o,i,r,h,d,p){return s(),e("div",null,[...i[0]||(i[0]=[l(`<h1 id="ep-05-联动不是监听-是维护依赖图" tabindex="-1">EP.05 联动不是监听，是维护依赖图 <a class="header-anchor" href="#ep-05-联动不是监听-是维护依赖图" aria-label="Permalink to &quot;EP.05 联动不是监听，是维护依赖图&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/05-formily-linkage">guide/05-formily-linkage</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君给省市区加了联动，选项能跟着变，但旧城市值没清掉，上线后出现「江苏省 + 杭州」的非法组合。</li><li><strong>揭秘</strong>：码叔指出 reactions 的本质是依赖追踪：函数里读过谁，就依赖谁；依赖变了，函数重跑。</li><li><strong>实证</strong>：像素酱补上异步校验与竞态：请求会失败、会乱序，错误必须对得上当前输入。</li><li><strong>结案</strong>：码叔用 effects 把生命周期写成日志，让联动从黑盒变成可观察的行为。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-替换选项不等于校验旧值" tabindex="-1">第一格：替换选项不等于校验旧值 <a class="header-anchor" href="#第一格-替换选项不等于校验旧值" aria-label="Permalink to &quot;第一格：替换选项不等于校验旧值&quot;">​</a></h3><p>省份切换时，城市字段的 <code>dataSource</code> 被替换成新列表，但 <code>field.value</code> 仍然是旧城市。表单看起来正常，提交时却是一个业务上不存在的组合。这类问题在手工测试里很难发现，因为页面每个控件都有值，只有后端知道这个组合不合法。</p><p>正确做法是在 reactions 里判断旧值是否还在新选项中，不在就置空：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">field.dataSource </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cities.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">city</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({ label: city.label, value: city.label }));</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (field.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cities.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">some</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">city</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city.label </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> field.value)) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  field.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>清理是联动的一部分，不是可选的收尾工作。</p><h3 id="第二格-依赖追踪的工作方式" tabindex="-1">第二格：依赖追踪的工作方式 <a class="header-anchor" href="#第二格-依赖追踪的工作方式" aria-label="Permalink to &quot;第二格：依赖追踪的工作方式&quot;">​</a></h3><p>函数式 reactions 里，<code>field.query(&quot;province&quot;).value()</code> 既是取值，也是声明依赖。Formily 记录这次读取，当省份变化时重新执行城市的 reactions。区县字段同时读取省份和城市，因此两者任一变化都会触发它，并沿「省份 → 城市 → 区县」的顺序级联清理。</p><p>表达式式 reactions 用 <code>dependencies</code> 显式声明依赖，用 <code>$deps</code> 按下标取值。它没有副作用能力，但可以被 JSON 序列化，适合计算合计、控制显隐这类「输入若干值，输出一个值」的逻辑。</p><h3 id="第三格-异步校验的竞态" tabindex="-1">第三格：异步校验的竞态 <a class="header-anchor" href="#第三格-异步校验的竞态" aria-label="Permalink to &quot;第三格：异步校验的竞态&quot;">​</a></h3><p><code>x-validator</code> 接受异步函数，返回字符串表示错误，返回空字符串表示通过。异步期间字段进入 validating 状态，控件可以显示 loading。</p><p>真正的风险是竞态：用户快速输入两次，两个请求同时在路上，先发出的请求可能后返回，页面就会显示一个过期的错误。生产环境至少要选一种处理：输入防抖、用 <code>AbortController</code> 取消旧请求、或给请求编号并丢弃过期结果。</p><h3 id="第四格-effects-的边界" tabindex="-1">第四格：effects 的边界 <a class="header-anchor" href="#第四格-effects-的边界" aria-label="Permalink to &quot;第四格：effects 的边界&quot;">​</a></h3><p>effects 是表单级生命周期：<code>onFormInit</code>、<code>onFieldValueChange</code>、<code>onFormSubmit</code> 等。它适合埋点、草稿、审计、权限校验，不适合放 UI 状态。把 loading、弹窗开关塞进 effects，会让表单和视图重新耦合。</p><p>本章的日志只保留最近八条，是观察工具，不是审计系统。真实审计应该把事件发到后端，而不是堆在页面上。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>只换选项不清旧值</strong>：提交时产生业务上不存在的组合。</li><li><strong>用 <code>visible</code> 当清空</strong>：隐藏字段仍参与取值与提交，需要隐藏即清空时在 <code>otherwise</code> 里置空。</li><li><strong>异步校验不处理竞态</strong>：错误可能来自三次输入之前。</li><li><strong>在 reactions 里直接读 <code>form.values</code></strong>：依赖不精确，容易读到旧值；优先用 <code>field.query</code>。</li><li><strong>把 UI 状态写进 effects</strong>：表单与视图重新耦合，测试也更难写。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 省份变化后，为什么城市值必须主动清理？</b></summary><p>因为替换选项只改变可选项，不会自动让旧值失效。旧城市可能不在新省份的列表里，如果不清空，表单会提交一个非法组合。Formily 不会自动替你判断业务合法性，清理是 Schema 作者的职责。</p></details><details><summary><b>2. 函数式 reactions 与表达式式 reactions 的边界是什么？</b></summary><p>函数式可以读写多个字段、修改 <code>dataSource</code>、调用外部函数，适合复杂联动；表达式式只能根据依赖计算值或状态，但可被 JSON 序列化，适合配置化与存库。需要序列化时优先表达式式。</p></details><details><summary><b>3. 异步校验器返回什么表示通过？</b></summary><p>返回空字符串（或 Promise resolve 空字符串）表示通过；返回非空字符串表示业务错误。返回布尔值、<code>undefined</code> 或抛异常，通常不会被当成可展示的业务错误。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/05-formily-linkage">第 05 章正文</a></li><li><a href="./../guide/04-formily-basics">第 04 章 · Formily 基础</a></li><li><a href="./../guide/06-formily-advanced">第 06 章 · 自定义字段</a></li></ul>`,27)])])}const g=a(t,[["render",n]]);export{k as __pageData,g as default};
